Client-Side SPA/Mobile Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Client-Side SPA/Mobile Container

Container_Boundary(client_side_container, "Client-Side SPA/Mobile Container") {
    Component(Patron Portal UI Component, "Patron Portal UI Component", "Web/Mobile Technologies, TypeScript", "Provides self-service portals and interfaces for patrons to browse catalogues and manage accounts.")
    Component(Staff App UI Component, "Staff App UI Component", "Web/Mobile Technologies, TypeScript", "Provides administrative and circulation management interfaces for library staff.")
    Component(State Management & Auth Component, "State Management & Auth Component", "OAuth 2.0 / OIDC, In-Memory Storage", "Handles token-based authentication and secure state management with in-memory storage for XSS mitigation.")
}

System(API Gateway Container, "API Gateway Container", "NGINX / Kong")

Rel(Patron Portal UI Component, API Gateway Container, "Sends API requests with correlation IDs", "HTTPS (REST/GraphQL)")
Rel(Staff App UI Component, API Gateway Container, "Sends API requests with correlation IDs", "HTTPS (REST/GraphQL)")

@enduml

API Gateway Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway_container, "API Gateway Container") {
    Component(Perimeter Security & TLS Termination Component, "Perimeter Security & TLS Termination Component", "NGINX / Kong", "Manages perimeter security, TLS termination, and JWT validation.")
    Component(Routing & Resilience Component, "Routing & Resilience Component", "NGINX / Kong", "Handles request routing, fail-open rate limiting, and token-based residency claims.")
    Component(Rate-Limit State Cache Component, "Rate-Limit State Cache Component", "Redis", "Maintains partitioned rate-limit state caching to support performance.")
}

Rel(Perimeter Security & TLS Termination Component, Routing & Resilience Component, "Passes authenticated and validated requests")
Rel(Routing & Resilience Component, Rate-Limit State Cache Component, "Checks and updates rate-limit states")
@enduml

Search Engine Container.diagram:
